/**
 * Team theme token sets — one per NFL team plus the neutral product-brand default.
 *
 * Each team carries luminance-tuned accent variants chosen for WCAG 2.2 AA
 * contrast (4.5:1 for text) against the light surface (#FFFFFF) and the dark
 * surface (#121418). Accents are derived from each club's primary brand color,
 * adjusted in lightness only (hue and saturation preserved) so team identity
 * survives the contrast fit. `accentContrast*` is the text color to set on
 * top of a filled accent, also AA-verified.
 *
 * Generated by /tmp/dcheck/gen-tokens.mjs; do not hand-edit hex values.
 * Regenerate if brand colors or surfaces change.
 */
export interface TeamThemeTokens {
  /** Canonical team abbreviation, e.g. 'KC'. Matches team_id in /api/v1. */
  teamId: string;
  name: string;
  abbr: string;
  /** Accent for light luminance. Contrast vs #FFFFFF: listed per team below. */
  accentLight: string;
  /** Accent for dark luminance. Contrast vs #121418: listed per team below. */
  accentDark: string;
  /** AA-verified text color on a filled accentLight. */
  accentContrastLight: string;
  /** AA-verified text color on a filled accentDark. */
  accentContrastDark: string;
}

