/** Neutral product-brand default accent (non-members, or members with accent source 'Neutral'). */
export const NEUTRAL_THEME: TeamThemeTokens = {
  teamId: 'neutral', name: 'Purging Light', abbr: 'PL', accentLight: '#1D4ED8', accentDark: '#5279E8', accentContrastLight: '#FFFFFF', accentContrastDark: '#000000',
}; // 6.70:1 light / 4.62:1 dark

const BY_ID = new Map<string, TeamThemeTokens>(TEAM_THEMES.map((t) => [t.teamId, t]));

/** Look up a team's token set by id; case-insensitive. Returns undefined for unknown ids. */
export function getTeamTheme(teamId: string): TeamThemeTokens | undefined {
  return BY_ID.get(teamId.toUpperCase());
}
